// Some portions generated by Claude
/**
 * The graph toolbar (explorer-toolbar.tsx) takes the first of three steps that fits its width, always on one row: its
 * buttons with their labels, with only their icons, or its compact form, where history and the Values and Labels
 * switches are rows of the Tools menu (`data-fit`, graph-explorer.css). Fixed widths cannot say when: the labels, a
 * filter count and the chosen view's name change what the toolbar takes. So it measures, and never wraps on its own.
 */

/** 0: labels; 1: icons; 2: compact. */
export type ToolbarLevel = 0 | 1 | 2;

/** The step shown, and what the toolbar took on one row at each step when last measured. */
export type ToolbarFit = { level: ToolbarLevel; widths: Array<number | undefined> };

const LEVEL_NAMES = ["labels", "icons", "compact"] as const;

/** The fit after measuring `width`, what the toolbar's contents take at the step shown, in `available` pixels. */
export function measuredFit(state: ToolbarFit, available: number, width: number): ToolbarFit {
  const widths = [...state.widths];
  widths[state.level] = width;
  const next = width > available && state.level < 2 ? ((state.level + 1) as ToolbarLevel) : state.level;
  return { level: next, widths };
}

/** The widest step that fitted this width when last measured, or was never measured; the current one otherwise. */
export function widestToTry(state: ToolbarFit, available: number): ToolbarLevel {
  let level = state.level;
  while (level > 0) {
    const width = state.widths[level - 1];
    if (width !== undefined && width > available) break;
    level = (level - 1) as ToolbarLevel;
  }
  return level;
}

/** What the toolbar's items take on one row: their widths, the gaps between them and the toolbar's padding. */
function contentWidth(bar: HTMLElement) {
  const style = getComputedStyle(bar);
  const items = [...bar.children] as HTMLElement[];
  const gap = Number.parseFloat(style.columnGap) || 0;
  return (
    items.reduce((sum, item) => sum + item.getBoundingClientRect().width, 0) +
    gap * Math.max(0, items.length - 1) +
    (Number.parseFloat(style.paddingLeft) || 0) +
    (Number.parseFloat(style.paddingRight) || 0)
  );
}

/**
 * Shows the step of the toolbar that fits its current width and returns the new fit: it tries the widest step that may
 * fit, then measures and steps down until one does, all before the browser paints, so no second row ever shows.
 */
export function fitToolbar(bar: HTMLElement, state: ToolbarFit): ToolbarFit {
  const available = bar.clientWidth;
  let next: ToolbarFit = { ...state, level: widestToTry(state, available) };
  bar.dataset.fit = LEVEL_NAMES[next.level];
  for (let step = 0; step < LEVEL_NAMES.length; step++) {
    const measured = measuredFit(next, available, contentWidth(bar));
    const moved = measured.level !== next.level;
    next = measured;
    bar.dataset.fit = LEVEL_NAMES[next.level];
    if (!moved) break;
  }
  return next;
}
